/* Actual directive results, native text and transactional metadata publication. */
static void EvalFatal(int level);
#define Q3_CHARACTER_FATAL_HOOK EvalFatal
#define main CharacterFixtureMain
#include "bot_character_regression.c"
#undef main
#include <limits.h>
#include <float.h>
extern int PC_Directive_eval(source_t *);
extern int PC_Directive_evalfloat(source_t *);
extern int PC_DollarDirective_evalint(source_t *);
extern int PC_DollarDirective_evalfloat(source_t *);
static int (*entries[4])(source_t *)={PC_Directive_eval,PC_Directive_evalfloat,PC_DollarDirective_evalint,PC_DollarDirective_evalfloat};
static int fatals,signMetadata=1;
static void EvalFatal(int level){Check(level==ERR_FATAL,"native copy-token fatal severity retained");fatals++;}
static source_t *EvalStart(const char *text){source_t *source;Reset(text);fatals=0;source=LoadSourceMemory((char *)text,(int)strlen(text),"native-eval");Check(source&&liveOwners==4&&!numtokens,"complete actual eval source imports");return source;}
static void EvalEnd(source_t *source){FreeSource(source);Check(!liveOwners&&!numtokens,"all eval/source/queued token owners physically release");}
static void EvalToken(int entry,const char *expression,const char *spelling,unsigned long integer,long double floating,int negative,int textOnly){source_t *source;token_t token;char body[1024];snprintf(body,sizeof(body),entry>=2?"(%s)":"%s\n",expression);source=EvalStart(body);Check(entries[entry](source),"actual native directive evaluates");if(negative){Check(PC_ReadToken(source,&token)&&token.type==TT_PUNCTUATION&&token.subtype==P_SUB&&!strcmp(token.string,"-"),"negative result retains native separate sign token");if(!textOnly&&signMetadata)Check(!token.intvalue&&!token.floatvalue,"sign numeric metadata initializes deterministically");}Check(PC_ReadToken(source,&token)&&!strcmp(token.string,spelling)&&token.type==TT_NUMBER&&token.subtype==((entry&1)?TT_FLOAT|TT_LONG|TT_DECIMAL:TT_INTEGER|TT_LONG|TT_DECIMAL),"native result spelling/type/subtype remain");if(!textOnly)Check(token.intvalue==integer&&token.floatvalue==floating&&token.linescrossed==0,"number metadata stores native magnitude consistently");Check(!PC_ReadToken(source,&token)&&!errors&&!fatals&&!numtokens,"complete native result then EOF without diagnostics");EvalEnd(source);}
static void EvalGoldens(int textOnly){int entry,value,count=0;for(entry=0;entry<4;entry++)for(value=-40;value<=40;value++){if(textOnly&&entry==3&&value<0)continue;char expression[64],spelling[64];long double magnitude=(long double)(value<0?-value:value);if(entry&1){double field=value/4.0;snprintf(expression,sizeof(expression),"%1.2f",field);snprintf(spelling,sizeof(spelling),"%1.2f",fabs(field));EvalToken(entry,expression,spelling,(unsigned long)fabs(field),fabsl((long double)field),value<0,textOnly);}else{snprintf(expression,sizeof(expression),"%d",value);snprintf(spelling,sizeof(spelling),"%d",value<0?-value:value);EvalToken(entry,expression,spelling,(unsigned long)magnitude,magnitude,value<0,textOnly);}count++;}Check(count==(textOnly?284:324),"all four native directive text/value cohorts compared");}
/* 1e20 exceeds unsigned long on LP64 and ILP32, and the lexer's digit-by-digit
   accumulation stays exact for it with a 64-bit long double (the PPC target). */
static void EvalWide(int entry){char expression[256],spelling[256];double value=1e20;snprintf(expression,sizeof(expression),"%1.0f.0",value);snprintf(spelling,sizeof(spelling),"%1.2f",value);EvalToken(entry,expression,spelling,ULONG_MAX,value,0,0);}
static void EvalLong(int maximum){char expression[256],spelling[256];unsigned long magnitude=maximum?(unsigned long)LONG_MAX:0UL-(unsigned long)LONG_MIN;snprintf(expression,sizeof(expression),"%lu",magnitude);snprintf(spelling,sizeof(spelling),"%lu",magnitude);EvalToken(0,expression,spelling,magnitude,magnitude,!maximum,0);EvalToken(2,expression,spelling,magnitude,magnitude,!maximum,0);}
static void EvalNonFinite(int entry,int nan){char value[256],body[1024],expression[1000];source_t *source;memset(value,'9',200);strcpy(value+200,".0");snprintf(expression,sizeof(expression),nan?"(%s * %s) - (%s * %s)":"%s * %s",value,value,value,value);snprintf(body,sizeof(body),entry>=2?"(%s)":"%s\n",expression);source=EvalStart(body);Check(!entries[entry](source)&&errors==1&&PC_SourceHasError(source)&&!source->tokens&&!numtokens&&liveOwners==4,"non-finite result rejects before text/casts/token publication");EvalEnd(source);}
static void EvalFailure(int entry,int sign){char body[128];source_t *source;int target,healthy;snprintf(body,sizeof(body),entry>=2?"(%s)":"%s\nnext",(entry&1)?"-0.5":"-7");source=EvalStart(body);Check(entries[entry](source),"actual output import trace prepares");healthy=requests;target=healthy-(sign?0:1);EvalEnd(source);source=EvalStart(body);failAt=target;Check(!entries[entry](source)&&requests==target&&fatals==1&&errors==1&&PC_SourceHasError(source),"nullable number/sign copy rejects atomically with native fatal severity");if(entry<2){Check(source->tokens&&!source->tokens->next&&!strcmp(source->tokens->string,"next")&&numtokens==1&&liveOwners==5,"native queued next-line owner survives failed signed result");}else Check(!source->tokens&&!numtokens&&liveOwners==4,"failed dollar signed result retains no partial output");EvalEnd(source);}
static void EvalPublic(void){source_t *source;token_t token;source=EvalStart("#eval 3 + 4\n#evalfloat 1.25\n$evalint(-7) $evalfloat(-5.25) tail");Check(PC_ReadToken(source,&token)&&token.intvalue==7&&token.floatvalue==7,"public hash eval initializes values");Check(PC_ReadToken(source,&token)&&token.intvalue==1&&token.floatvalue==1.25,"public hash float initializes values");Check(PC_ReadToken(source,&token)&&!strcmp(token.string,"-"),"public dollar integer sign");Check(PC_ReadToken(source,&token)&&token.intvalue==7&&token.floatvalue==7,"public dollar integer magnitude");Check(PC_ReadToken(source,&token)&&!strcmp(token.string,"-"),"public dollar float sign");Check(PC_ReadToken(source,&token)&&token.intvalue==5&&token.floatvalue==5.25,"public dollar float magnitude");Check(PC_ReadToken(source,&token)&&!strcmp(token.string,"tail")&&!PC_ReadToken(source,&token)&&!errors&&!numtokens,"public directive flow preserves following token");EvalEnd(source);}
static void EvalCharacter(void){bot_character_t *character;Reset("skill 4 { 0 $evalint(42) 1 $evalfloat(1.25) 79 \"owned\" }");character=BotLoadCharacterFromFile("bots/native.c",4);Check(character&&character->c[0].type==CT_INTEGER&&character->c[0].value.integer==42&&character->c[1].type==CT_FLOAT&&character->c[1].value._float==1.25&&character->c[79].type==CT_STRING&&!strcmp(character->c[79].value.string,"owned")&&!errors,"real native character fields consume complete expression metadata");Release(character);}
#ifndef Q3_EVAL_ENTRY
#define Q3_EVAL_ENTRY main
#endif
int Q3_EVAL_ENTRY(int argc,char **argv){if(argc>1){int proof=atoi(argv[1]);signMetadata=0;if(proof==0)EvalToken(0,"7","7",7,7,0,0);else if(proof==1)EvalToken(1,"1.25","1.25",1,1.25,0,0);else if(proof==2)EvalToken(2,"-7","7",7,7,1,0);else if(proof==3)EvalToken(3,"-5.25","5.25",5,5.25,1,0);else if(proof==4)EvalWide(3);else if(proof==5)EvalLong(0);else if(proof==6)EvalLong(1);else if(proof==7)EvalNonFinite(3,0);else if(proof==8)EvalNonFinite(1,1);else if(proof>=9&&proof<=16)EvalFailure((proof-9)/2,(proof-9)%2);else EvalGoldens(1);return 0;}EvalGoldens(0);EvalWide(1);EvalWide(3);EvalLong(0);EvalLong(1);EvalPublic();EvalCharacter();{int entry,sign;for(entry=0;entry<4;entry++){if(entry&1){EvalNonFinite(entry,0);EvalNonFinite(entry,1);}for(sign=0;sign<2;sign++)EvalFailure(entry,sign);}}puts("Real expression token magnitude metadata, native text, finite casts and atomic copy rollback passed (issue #48)");return 0;}
